import{_ as t,o as a,c as o,ag as s}from"./chunks/framework.CPBr0c_K.js";const u=JSON.parse('{"title":"API","description":"","frontmatter":{},"headers":[],"relativePath":"guide/api.md","filePath":"guide/api.md","lastUpdated":1777082248000}'),d={name:"guide/api.md"};function n(i,e,c,r,l,p){return a(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="api" tabindex="-1">API <a class="header-anchor" href="#api" aria-label="Permalink to &quot;API&quot;">​</a></h1><h3 id="syncsession-t-recommended" tabindex="-1"><code>SyncSession&lt;T&gt;</code> (recommended) <a class="header-anchor" href="#syncsession-t-recommended" aria-label="Permalink to &quot;`SyncSession&lt;T&gt;` (recommended)&quot;">​</a></h3><p>For state synchronization between two endpoints, use <code>SyncSession&lt;T&gt;</code> — a stateful handle that manages the full-vs-diff distinction and keeps both sides in sync automatically. First call on each side is a full encode/decode; subsequent calls are deltas against the accumulated view.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>       sender.encode(state) ──→ [bytes] ──→ receiver.decode(bytes) ──→ state</span></span></code></pre></div><p>Both the server and the client create a <code>SyncSession&lt;T&gt;</code>, and each one handles the full-encode bootstrap and every subsequent diff internally. The session guarantees that sender and receiver stay aligned even when the server&#39;s state is mutated in ways that reorder internal collections.</p><h3 id="low-level-api-advanced" tabindex="-1">Low-level API (advanced) <a class="header-anchor" href="#low-level-api-advanced" aria-label="Permalink to &quot;Low-level API (advanced)&quot;">​</a></h3><p>Every object and union type also exposes stateless primitives. Use these if you need full control — multi-baseline diffs, custom transport protocols, ack-based history, etc.:</p><table tabindex="0"><thead><tr><th>Function</th><th>Description</th></tr></thead><tbody><tr><td><code>encode(obj) → bytes</code></td><td>Serialize to binary</td></tr><tr><td><code>decode(bytes) → obj</code></td><td>Deserialize from binary</td></tr><tr><td><code>encodeDiff(prev, next) → bytes</code></td><td>Delta-compress only the changes between two states</td></tr><tr><td><code>decodeDiff(prev, diff) → obj</code></td><td>Apply a delta to reconstruct the new state</td></tr><tr><td><code>equals(a, b) → bool</code></td><td>Deep equality comparison (respects float precision)</td></tr><tr><td><code>clone(obj) → obj</code></td><td>Deep clone</td></tr><tr><td><code>fromJson(json) → obj</code></td><td>Parse from JSON with lenient type coercion</td></tr><tr><td><code>toJson(obj) → json</code></td><td>Convert to a JSON-serializable representation</td></tr></tbody></table><p>When using these directly, <code>prev</code> passed to <code>encodeDiff</code> / <code>decodeDiff</code> <strong>must match the peer&#39;s wire view exactly</strong> (same key insertion order in maps, not just the same key-value content). Mismatch causes silent corruption. <code>SyncSession</code> exists specifically to guarantee this invariant for you — prefer it unless you need manual control.</p>',9)])])}const b=t(d,[["render",n]]);export{u as __pageData,b as default};
